"""Behavior tests use generated bytes and labels, never bank data."""
import csv
import hashlib
import importlib.util
import json
from pathlib import Path
import tempfile
import unittest

MODULE = Path(__file__).resolve().parents[2] / "scripts/data/freeze_split.py"
spec = importlib.util.spec_from_file_location("freeze_split", MODULE)
split = importlib.util.module_from_spec(spec)
spec.loader.exec_module(split)


class FrozenSplitTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.audit = self.root / "audit"
        self.audit.mkdir()
        self.rows = []
        self.labels = []
        self.checks = []
        for index in range(1, 13):
            data = f"SYNTHETIC FILE {index}".encode()
            path = self.root / f"video-{index}.mov"
            path.write_bytes(data)
            sha = hashlib.sha256(data).hexdigest()
            verdict = "violation" if index <= 6 else "no_violation"
            stamp = "2.5" if index <= 6 else ""
            self.rows.append({"canonical_id": f"X-{index}", "relative_path": path.name, "sha256": sha,
                              "bytes": len(data), "duration_sec": "10", "rotation_degrees": "0",
                              "verdict": verdict, "timestamp_sec": stamp, "probe_returncode": "0"})
            self.labels.append({"canonical_id": f"X-{index}", "verdict": verdict, "timestamp_sec": stamp})
            self.checks.append({"sha256": sha, "status": "ok", "returncode": 0, "progress": "end", "decoded_frames": 10, "stderr": ""})
        # Exact copy with a different weak source timestamp: it must stay together.
        duplicate = dict(self.rows[0], canonical_id="X-47", relative_path="copy.mov", timestamp_sec="3.5")
        (self.root / "copy.mov").write_bytes((self.root / "video-1.mov").read_bytes())
        self.rows.append(duplicate)
        self.labels.append({"canonical_id": "X-47", "verdict": "violation", "timestamp_sec": "3.5"})
        self.write_inputs()

    def write_inputs(self):
        for filename, rows in (("video_manifest.csv", self.rows), ("labels_normalized.csv", self.labels)):
            with (self.audit / filename).open("w", encoding="utf-8", newline="") as stream:
                writer = csv.DictWriter(stream, fieldnames=list(rows[0]))
                writer.writeheader()
                writer.writerows(rows)
        (self.audit / "decode_checks.json").write_text(json.dumps(self.checks), encoding="utf-8")

    def args(self, command, *extra):
        result = [command, "--audit-dir", str(self.audit), "--data-root", str(self.root), "--receipt", str(self.root / "receipt.json")]
        if command == "freeze":
            result += ["--out", str(self.root / "frozen"), "--sizes", "6", "2", "4"]
        else:
            result += ["--freeze", str(self.root / "frozen")]
        return split.parser().parse_args(result + list(extra))

    def freeze(self, *extra):
        return split.freeze(self.args("freeze", *extra))

    def read_manifest(self):
        return split.read_json(self.root / "frozen/frozen.json")

    def groups_file(self, groups=(), complete=True):
        path = self.root / "groups.json"
        path.write_bytes(split.encoded({"schema_version": "1", "review_status": "complete" if complete else "pending", "groups": list(groups)}))
        return path

    def test_reproducible_stratified_hash_groups_and_protected_group(self):
        receipt = self.freeze()
        manifest, _ = split.validate(self.args("validate"))
        by_id = {row["canonical_id"]: row for row in manifest["records"]}
        self.assertEqual(by_id["X-1"]["split"], by_id["X-47"]["split"])
        self.assertNotEqual(by_id["X-47"]["split"], "test")
        self.assertNotEqual(by_id["X-4"]["split"], "test")
        self.assertEqual([receipt["summary"][name]["unique_videos"] for name in split.SPLITS], [6, 2, 4])
        self.assertEqual([receipt["summary"][name]["positive"] for name in split.SPLITS], [3, 1, 2])
        # Source CSV ordering is irrelevant for allocation; raw fingerprint still changes.
        reversed_rows = list(reversed(manifest["records"]))
        groups = split.make_groups(reversed_rows, split.group_config())
        assignment, _ = split.allocate(groups, [6, 2, 4], manifest["seed"], manifest["no_test_ids"])
        self.assertEqual(assignment, {g["group_id"]: g["split"] for g in manifest["groups"]})
        text = json.dumps(receipt)
        for key in ("canonical_id", "relative_path", "source_timestamp_sec", "members", "verdict"):
            self.assertNotIn(f'"{key}"', text)
        self.assertFalse(receipt["model_tuning_allowed"])

    def test_freeze_never_overwrites(self):
        self.freeze()
        old = (self.root / "frozen/frozen.json").read_bytes()
        with self.assertRaisesRegex(split.SplitError, "already exists"):
            self.freeze("--seed", "9")
        self.assertEqual(old, (self.root / "frozen/frozen.json").read_bytes())

    def test_detects_modified_manifest(self):
        self.freeze()
        path = self.root / "frozen/frozen.json"
        path.write_bytes(path.read_bytes() + b" ")
        with self.assertRaisesRegex(split.SplitError, "hash differs"):
            split.validate(self.args("validate"))

    def test_detects_changed_audit_fingerprint(self):
        self.freeze()
        path = self.audit / "labels_normalized.csv"
        path.write_bytes(path.read_bytes() + b"\n")
        with self.assertRaisesRegex(split.SplitError, "fingerprint changed"):
            split.validate(self.args("validate"))

    def test_detects_changed_video_bytes(self):
        self.freeze()
        path = self.root / "video-1.mov"
        path.write_bytes(b"X" * path.stat().st_size)
        with self.assertRaisesRegex(split.SplitError, "Source bytes differ"):
            split.validate(self.args("validate"))

    def test_conflicting_duplicate_labels_rejected(self):
        self.rows[-1]["verdict"] = self.labels[-1]["verdict"] = "no_violation"
        self.rows[-1]["timestamp_sec"] = self.labels[-1]["timestamp_sec"] = ""
        self.write_inputs()
        with self.assertRaisesRegex(split.SplitError, "conflicting binary labels"):
            self.freeze()

    def test_decode_failure_rejected(self):
        self.checks[0]["status"] = "error_or_warning"
        self.write_inputs()
        with self.assertRaisesRegex(split.SplitError, "incomplete or failed"):
            self.freeze()

    def test_missing_label_rejected(self):
        self.labels.pop()
        self.write_inputs()
        with self.assertRaisesRegex(split.SplitError, "one-to-one"):
            self.freeze()

    def test_unknown_manual_group_rejected(self):
        path = self.groups_file([["X-1", "X-999"]])
        with self.assertRaisesRegex(split.SplitError, "unknown source identifier"):
            self.freeze("--groups", str(path))

    def test_manual_groups_are_indivisible_including_transitive_duplicate(self):
        path = self.groups_file([["X-1", "X-2"], ["X-2", "X-7"]])
        self.freeze("--groups", str(path))
        rows = {row["canonical_id"]: row for row in self.read_manifest()["records"]}
        self.assertEqual(len({rows[key]["group_id"] for key in ("X-1", "X-2", "X-7", "X-47")}), 1)
        self.assertEqual(len({rows[key]["split"] for key in ("X-1", "X-2", "X-7", "X-47")}), 1)
        split.validate(self.args("validate"))

    def test_pending_review_blocks_export_and_no_test_in_ml_manifest(self):
        self.freeze()
        with (self.root / "frozen/train_dev.csv").open() as stream:
            rows = list(csv.DictReader(stream))
        self.assertEqual({r["split"] for r in rows}, {"train", "dev"})
        with self.assertRaisesRegex(split.SplitError, "review is pending"):
            split.export(self.args("export-train-dev", "--out", str(self.root / "ml")))
        self.assertFalse((self.root / "ml").exists())

    def test_review_rejects_cross_split_similarity(self):
        self.freeze()
        records = self.read_manifest()["records"]
        train = next(row["canonical_id"] for row in records if row["split"] == "train")
        test = next(row["canonical_id"] for row in records if row["split"] == "test")
        path = self.groups_file([[train, test]])
        with self.assertRaisesRegex(split.SplitError, "cross frozen splits"):
            split.review(self.args("review", "--groups", str(path)))
        self.assertFalse((self.root / "frozen/group_review.json").exists())

    def test_review_and_export_include_only_train_dev(self):
        self.freeze()
        path = self.groups_file()
        result = split.review(self.args("review", "--groups", str(path)))
        self.assertTrue(result["model_tuning_allowed"])
        package = split.export(self.args("export-train-dev", "--out", str(self.root / "ml")))
        with (self.root / "ml/train_dev.csv").open() as stream:
            records = list(csv.DictReader(stream))
        self.assertEqual({row["split"] for row in records}, {"train", "dev"})
        self.assertNotIn("test", package["summary"])
        expected = {row["canonical_id"] for row in self.read_manifest()["records"] if row["split"] != "test"}
        self.assertEqual({row["canonical_id"] for row in records}, expected)
        self.assertEqual({p.stem for p in (self.root / "ml/videos").iterdir()}, expected)
        self.assertEqual({p.name for p in (self.root / "ml").iterdir()}, {"videos", "train_dev.csv", "package.json"})
        with self.assertRaisesRegex(split.SplitError, "already exists"):
            split.review(self.args("review", "--groups", str(path)))

    def test_impossible_group_sizes_fail_without_random_retry(self):
        path = self.groups_file([[f"X-{i}" for i in range(1, 9)]])
        with self.assertRaisesRegex(split.SplitError, "cannot satisfy"):
            self.freeze("--groups", str(path))

    def test_escape_path_rejected(self):
        self.rows[0]["relative_path"] = "../outside.mov"
        self.write_inputs()
        with self.assertRaisesRegex(split.SplitError, "must be relative"):
            self.freeze()


if __name__ == "__main__":
    unittest.main()
